import{_ as e,C as t,c as r,o as l,a0 as n,b as i,w as a,a as s,G as o,a1 as d}from"./chunks/framework.DKRgXLPU.js";const u=JSON.parse('{"title":"Øktguide: Introduksjon til mentalt spill (2–3 timer)","description":"","frontmatter":{},"headers":[],"relativePath":"no/mental-journey/session-guide.md","filePath":"no/mental-journey/session-guide.md"}');const g=e({name:"no/mental-journey/session-guide.md"},[["render",function(e,u,g,k,p,m){const h=t("Mermaid");return l(),r("div",null,[u[1]||(u[1]=n('<h1 id="øktguide-introduksjon-til-mentalt-spill-2–3-timer" tabindex="-1">Øktguide: Introduksjon til mentalt spill (2–3 timer) <a class="header-anchor" href="#øktguide-introduksjon-til-mentalt-spill-2–3-timer" aria-label="Permalink to &quot;Øktguide: Introduksjon til mentalt spill (2–3 timer)&quot;">​</a></h1><h2 id="oversikt" tabindex="-1">Oversikt <a class="header-anchor" href="#oversikt" aria-label="Permalink to &quot;Oversikt&quot;">​</a></h2><p>Denne veiledningen hjelper deg med å gjennomføre en 2–3 timers introduksjonsøkt i mental spilltrening for petanquespillere. Perfekt for trenere, klubbledere eller erfarne spillere som ønsker å introdusere mental trening for laget sitt.</p><div class="tip custom-block"><p class="custom-block-title">To deler i denne veiledningen</p><ul><li><strong><a href="#for-deltakere">For deltakere</a></strong> – Hva spillerne vil lære</li><li><strong><a href="#for-tilretteleggere">For tilretteleggere</a></strong> - Slik gjennomfører du økten</li></ul></div><h2 id="hurtigtilgang" tabindex="-1">Hurtigtilgang <a class="header-anchor" href="#hurtigtilgang" aria-label="Permalink to &quot;Hurtigtilgang&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Del</th><th>Hensikt</th><th>Adgang</th></tr></thead><tbody><tr><td><strong>For deltakere</strong></td><td>Hva du kan forvente av økten</td><td><a href="#for-deltakere">Vis seksjon</a></td></tr><tr><td><strong>For fasilitatorer</strong></td><td>Fullstendig øktplan og tidspunkt</td><td><a href="#for-tilretteleggere">Vis seksjon</a></td></tr><tr><td><strong>Materialer for økten</strong></td><td>Guider, lysbilder og arbeidsark</td><td><a href="/no/mental-reise/materialer">Se materiale</a></td></tr><tr><td><strong>Sjekkliste for forberedelser</strong></td><td>Hva du bør forberede før økten</td><td><a href="#forberedelse-1-uke-før">Se sjekkliste</a></td></tr></tbody></table><hr><h2 id="for-deltakere" tabindex="-1">For deltakere <a class="header-anchor" href="#for-deltakere" aria-label="Permalink to &quot;For deltakere&quot;">​</a></h2><h3 id="hva-du-kan-forvente" tabindex="-1">Hva du kan forvente <a class="header-anchor" href="#hva-du-kan-forvente" aria-label="Permalink to &quot;Hva du kan forvente&quot;">​</a></h3><p>Denne økten introduserer det mentale spillet petanque gjennom diskusjoner, øvelser og praktiske teknikker du kan bruke umiddelbart.</p><p><strong>Du vil lære:</strong></p><ul><li>Hvorfor mental trening er viktig for prestasjoner</li><li>Forskjellen mellom &quot;teknisk modus&quot; og &quot;flytmodus&quot;</li><li>Hvordan gjenkjenne og håndtere din indre kritiker</li><li>Enkle teknikker for trykkhåndtering</li><li>En grunnleggende rutine før inntak</li></ul><p><strong>Det du trenger:</strong></p><ul><li>Åpent sinn og vilje til å dele</li><li>Notisbok og penn</li><li>Dine egne erfaringer å diskutere</li><li>2–3 timer med fokusert tid</li></ul><h3 id="øktstruktur" tabindex="-1">Øktstruktur <a class="header-anchor" href="#øktstruktur" aria-label="Permalink to &quot;Øktstruktur&quot;">​</a></h3>',15)),(l(),i(d,null,{default:a(()=>[o(h,{id:"mermaid-155",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BIntroduksjon%20%3Cbr%2F%3E%2020%20minutter%5D%20--%3E%20B%5BSonen%20%3Cbr%2F%3E%2040%20minutter%5D%0A%20%20%20%20B%20--%3E%20C%5BBrudd%20%3Cbr%2F%3E%2010%20minutter%5D%0A%20%20%20%20C%20--%3E%20D%5BIndre%20kritiker%20%3Cbr%2F%3E%2040%20minutter%5D%0A%20%20%20%20D%20--%3E%20E%5BPraktiske%20verkt%C3%B8y%20%3Cbr%2F%3E%2040%20minutter%5D%0A%20%20%20%20E%20--%3E%20F%5BIntegrering%20%3Cbr%2F%3E%2020%20minutter%5D%0A%20%20%20%20%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20B%20fill%3A%23fff4e1%0A%20%20%20%20style%20C%20fill%3A%23f3e5f5%0A%20%20%20%20style%20D%20fill%3A%23ffe4e1%0A%20%20%20%20style%20E%20fill%3A%23e8f5e9%0A%20%20%20%20style%20F%20fill%3A%23c8e6c9%0A"})]),fallback:a(()=>[...u[0]||(u[0]=[s(" Loading... ",-1)])]),_:1})),u[2]||(u[2]=n('<h3 id="nøkkelbegreper-du-vil-utforske" tabindex="-1">Nøkkelbegreper du vil utforske <a class="header-anchor" href="#nøkkelbegreper-du-vil-utforske" aria-label="Permalink to &quot;Nøkkelbegreper du vil utforske&quot;">​</a></h3><h4 id="_1-sonen-flyttilstand" tabindex="-1">1. Sonen (flyttilstand) <a class="header-anchor" href="#_1-sonen-flyttilstand" aria-label="Permalink to &quot;1. Sonen (flyttilstand)&quot;">​</a></h4><ul><li>Hvordan det føles når alt klikker</li><li>Hvorfor det å tenke på teknikk forstyrrer ytelsen</li><li>«Bryteren» fra planlegging til utførelse</li></ul><h4 id="_2-den-indre-kritikeren" tabindex="-1">2. Den indre kritikeren <a class="header-anchor" href="#_2-den-indre-kritikeren" aria-label="Permalink to &quot;2. Den indre kritikeren&quot;">​</a></h4><ul><li>Hvordan negativ selvsnakk påvirker prestasjonen</li><li>Forskjellen mellom indre kritiker og indre coach</li><li>Nøytral observasjon kontra hard vurdering</li></ul><h4 id="_3-trykkrespons" tabindex="-1">3. Trykkrespons <a class="header-anchor" href="#_3-trykkrespons" aria-label="Permalink to &quot;3. Trykkrespons&quot;">​</a></h4><ul><li>Hvorfor du spiller annerledes i konkurranser</li><li>Fysiske tegn på press</li><li>Teknikker for rask tilbakestilling</li></ul><h4 id="_4-praktiske-verktøy" tabindex="-1">4. Praktiske verktøy <a class="header-anchor" href="#_4-praktiske-verktøy" aria-label="Permalink to &quot;4. Praktiske verktøy&quot;">​</a></h4><ul><li>3-pustetilbakestilling</li><li>Enkel rutine før inntak</li><li>Protokoll for feilgjenoppretting</li></ul><h3 id="hva-du-skal-ta-med" tabindex="-1">Hva du skal ta med <a class="header-anchor" href="#hva-du-skal-ta-med" aria-label="Permalink to &quot;Hva du skal ta med&quot;">​</a></h3><p><strong>Påkrevd:</strong></p><ul><li>Deg selv og dine erfaringer</li><li>Villighet til å delta</li></ul><p><strong>Valgfri:</strong></p><ul><li>Eksempler på mentale utfordringer du står overfor</li><li>Spørsmål om spesifikke situasjoner</li><li>Notatbok for personlige notater</li></ul><h3 id="etter-sesjonen" tabindex="-1">Etter sesjonen <a class="header-anchor" href="#etter-sesjonen" aria-label="Permalink to &quot;Etter sesjonen&quot;">​</a></h3><p>Du vil motta:</p><ul><li>Sammendrag av nøkkelbegreper</li><li>Øvelser for uken</li><li>Lenker til detaljerte utdanningsmoduler</li><li>Målmal for mental spillutvikling</li></ul><hr><h2 id="for-fasilitatorer" tabindex="-1">For fasilitatorer <a class="header-anchor" href="#for-fasilitatorer" aria-label="Permalink to &quot;For fasilitatorer&quot;">​</a></h2><h3 id="forberedelsessjekkliste" tabindex="-1">Forberedelsessjekkliste <a class="header-anchor" href="#forberedelsessjekkliste" aria-label="Permalink to &quot;Forberedelsessjekkliste&quot;">​</a></h3><p><strong>1 uke før:</strong></p><ul><li>[ ] Bestill rom i 2–3 timer</li><li>[ ] Inviter 6–12 deltakere</li><li>[ ] Bokmerk materialsider (se <a href="/no/mental-journey/materials">Materialer</a>)</li><li>[ ] Les denne veiledningen grundig</li><li>[ ] Forbered flippover eller tavle</li></ul><p><strong>1 dag før:</strong></p><ul><li>[ ] Bekreft oppmøte</li><li>[ ] Sett opp rommet (sirkel sitteplasser)</li><li>[ ] Test all teknologi (lysbilder osv.)</li><li>[ ] Forbered materialer</li></ul><p><strong>1 time før:</strong></p><ul><li>[ ] Kom tidlig</li><li>[ ] Sett opp sitteplasser i sirkel</li><li>[ ] Sett opp materialer</li><li>[ ] Sentrer deg selv</li></ul><h3 id="din-rolle-som-tilrettelegger" tabindex="-1">Din rolle som tilrettelegger <a class="header-anchor" href="#din-rolle-som-tilrettelegger" aria-label="Permalink to &quot;Din rolle som tilrettelegger&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Viktig</p><p>Du er <strong>ikke</strong> en terapeut eller teknisk coach. Du er en <strong>fasilitator</strong> som:</p><ul><li>Guider-diskusjon</li><li>Skaper trygg plass</li><li>Kobler konsepter til erfaring</li><li>Styrer gruppedynamikk</li></ul></div><p><strong>Nøkkelferdigheter:</strong></p><ul><li>Aktiv lytting</li><li>Nøytral tilstedeværelse</li><li>Håndtering av ulike personligheter</li><li>Å vite når man skal gå videre</li></ul><h3 id="detaljert-øktplan" tabindex="-1">Detaljert øktplan <a class="header-anchor" href="#detaljert-øktplan" aria-label="Permalink to &quot;Detaljert øktplan&quot;">​</a></h3><hr><h4 id="del-1-introduksjon-20-minutter" tabindex="-1">Del 1: Introduksjon (20 minutter) <a class="header-anchor" href="#del-1-introduksjon-20-minutter" aria-label="Permalink to &quot;Del 1: Introduksjon (20 minutter)&quot;">​</a></h4><p><strong>Mål:</strong></p><ul><li>Skape psykologisk trygghet</li><li>Sett forventninger</li><li>Bygg gruppeforbindelse</li></ul><p><strong>Manus:</strong></p><p>&quot;Velkommen alle sammen. Denne økten handler om det mentale spillet petanque – tankene, følelsene og mønstrene som påvirker prestasjonen din.&quot;</p><p><strong>Grunnregler:</strong></p><ol><li>Det som deles her forblir her</li><li>Ingen dom over andres erfaringer</li><li>Deltakelse er frivillig</li><li>Det finnes ingen gale svar</li></ol><p><strong>Kursrunde:</strong> Navn, hvor lenge du har spilt, én mental utfordring du står overfor.</p><p><strong>Merknader til veileder:</strong></p><ul><li>Gå først til modellering av sårbarhet</li><li>Hold introduksjonene korte (1 minutt hver)</li><li>Legg merke til vanlige temaer</li><li>Valider alle svar</li></ul><hr><h4 id="del-2-sone-flyttilstanden-40-minutter" tabindex="-1">Del 2: Sone-/flyttilstanden (40 minutter) <a class="header-anchor" href="#del-2-sone-flyttilstanden-40-minutter" aria-label="Permalink to &quot;Del 2: Sone-/flyttilstanden (40 minutter)&quot;">​</a></h4><p><strong>Mål:</strong></p><ul><li>Forstå flyttilstander</li><li>Gjenkjenne teknisk kontra flytmodus</li><li>Lær deg «bytte»-konseptet</li></ul><p><strong>Åpningsspørsmål:</strong> «Tenk på en gang du spilte din beste petanque. Hvordan føltes det? Hva var annerledes?»</p><p><strong>Diskusjonsspørsmål:</strong></p><ol><li>«Hvor mange av dere har hatt spill der alt bare klikket?»</li><li>&quot;Hva tenkte du på i disse øyeblikkene?&quot;</li><li>«Hvordan er det annerledes enn når du sliter?»</li></ol><p><strong>Viktige læringspunkter:</strong></p><p>Bruk tavlen til å tegne:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PLANNING MODE          →    EXECUTION MODE</span></span>\n<span class="line"><span>(Outside circle)            (Inside circle)</span></span>\n<span class="line"><span>- Analyze situation         - Eyes on target</span></span>\n<span class="line"><span>- Choose strategy           - Trust training</span></span>\n<span class="line"><span>- Decide throw type         - Automatic movement</span></span></code></pre></div><p><strong>Øvelse: Bryteren (10 minutter)</strong></p><p>&quot;La oss øve på bytteøyeblikket:&quot;</p><ol><li>Stå opp</li><li>Tenk deg at du er utenfor sirkelen – tenk på et skudd</li><li>Ta et pust</li><li>Gå fremover (inn i en imaginær sirkel)</li><li>Slipp analysen når du går fremover</li><li>Fokuser kun på et imaginært mål&quot;</li></ol><p><strong>Oppsummering:</strong></p><ul><li>&quot;Hva la du merke til?&quot;</li><li>«Var det lett eller vanskelig å gi slipp på tanken?»</li><li>&quot;Hvordan kan dette gjelde i ekte spill?&quot;</li></ul><hr><h4 id="del-3-pause-10-minutter" tabindex="-1">Del 3: Pause (10 minutter) <a class="header-anchor" href="#del-3-pause-10-minutter" aria-label="Permalink to &quot;Del 3: Pause (10 minutter)&quot;">​</a></h4><p><strong>Tilretteleggerens handlinger:</strong></p><ul><li>Oppmuntre til uformell diskusjon</li><li>Legg merke til gruppeenergi</li><li>Forbered deg til neste avsnitt</li></ul><hr><h4 id="del-4-den-indre-kritikeren-40-minutter" tabindex="-1">Del 4: Den indre kritikeren (40 minutter) <a class="header-anchor" href="#del-4-den-indre-kritikeren-40-minutter" aria-label="Permalink to &quot;Del 4: Den indre kritikeren (40 minutter)&quot;">​</a></h4><p><strong>Mål:</strong></p><ul><li>Gjenkjenn negative selvsnakkmønstre</li><li>Skille mellom indre kritiker og indre coach</li><li>Øv deg på nøytral observasjon</li></ul><p><strong>Åpning:</strong> «Vi har alle en indre stemme som kommenterer prestasjonene våre. Noen ganger er det nyttig, noen ganger er det hardt. La oss utforske det.»</p><p><strong>Øvelse: Indre kritiker-inventar (15 minutter)</strong></p><p>&quot;Skriv ned på papiret ditt:&quot;</p><ol><li>Hva din indre stemme sier etter et dårlig kast</li><li>Hva det sier når du er under press</li><li>Hva det sier om dine evner&quot;</li></ol><p><em>Gi 5 minutter til skriving</em></p><p>«Hvem er villig til å dele ett eksempel nå?»</p><p><strong>Merknader til veileder:</strong></p><ul><li>Normaliser hard selvsnakk</li><li>Ikke prøv å «fikse» noen</li><li>Se etter vanlige mønstre</li></ul><p><strong>Undervisning: Indre kritiker vs. indre coach (15 minutter)</strong></p><p>Tegn to kolonner på tavlen:</p><table tabindex="0"><thead><tr><th>Indre kritiker</th><th>Indre trener</th></tr></thead><tbody><tr><td>&quot;Hvordan kunne du gå glipp av det?!&quot;</td><td>&quot;Det gikk til venstre&quot;</td></tr><tr><td>&quot;Du kveles alltid&quot;</td><td>&quot;La oss prøve igjen&quot;</td></tr><tr><td>&quot;Du er forferdelig&quot;</td><td>&quot;Hva kan jeg lære?&quot;</td></tr></tbody></table><p><strong>Diskusjon:</strong></p><ul><li>&quot;Merker du forskjellen?&quot;</li><li>&quot;Hvilken stemme hjelper fremføringen?&quot;</li><li>&quot;Kan du endre stemmen?&quot;</li></ul><p><strong>Øvelse: Omformulering (10 minutter)</strong></p><p>«Ta en av dine indre kritiker-utsagn. Hvordan ville en indre coach sagt den?»</p><p>Del eksempler.</p><hr><h4 id="del-5-praktiske-verktøy-40-minutter" tabindex="-1">Del 5: Praktiske verktøy (40 minutter) <a class="header-anchor" href="#del-5-praktiske-verktøy-40-minutter" aria-label="Permalink to &quot;Del 5: Praktiske verktøy (40 minutter)&quot;">​</a></h4><p><strong>Mål:</strong></p><ul><li>Lær 3-pustet tilbakestilling</li><li>Lag en enkel rutine før inntak</li><li>Forstå feilgjenoppretting</li></ul><p><strong>Verktøy 1: 3-pustetilbakestilling (10 minutter)</strong></p><p>«Dette er tilbakestillingsknappen din i nødstilfeller. Bruk den når du føler at trykket øker.»</p><p><strong>Demonstrere:</strong></p><ol><li>Pust inn i 4 tellinger</li><li>Hold i 2 tellinger</li><li>Pust ut i 6 tellinger</li><li>Gjenta 3 ganger</li></ol><p>«La oss øve sammen nå.»</p><p><em>Lede gruppen gjennom 3 sykluser</em></p><p><strong>Oppsummering:</strong></p><ul><li>&quot;Hva la du merke til i kroppen din?&quot;</li><li>&quot;Når kan du bruke dette?&quot;</li></ul><p><strong>Verktøy 2: Enkel rutine før fotografering (15 minutter)</strong></p><p>«En rutine hjelper deg med å gå fra planlegging til utførelse konsekvent.»</p><p><strong>Grunnleggende struktur:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Outside Circle (Planning):</span></span>\n<span class="line"><span>- Look at situation</span></span>\n<span class="line"><span>- Decide on throw</span></span>\n<span class="line"><span>- See the result in your mind</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Walking to Circle (Transition):</span></span>\n<span class="line"><span>- One deep breath</span></span>\n<span class="line"><span>- Let go of analysis</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Inside Circle (Execution):</span></span>\n<span class="line"><span>- Eyes on target only</span></span>\n<span class="line"><span>- Trust your training</span></span>\n<span class="line"><span>- Execute</span></span></code></pre></div><p><strong>Øvelse:</strong> &quot;Lag din egen 3-trinnsrutine. Skriv den ned.&quot;</p><p>Del eksempler.</p><p><strong>Verktøy 3: Protokoll for feilgjenoppretting (15 minutter)</strong></p><p>«Elitespillere gjør ikke færre feil. De kommer seg raskere.»</p><p><strong>3-trinns protokoll:</strong></p><ol><li><strong>Observer</strong> - Angi faktum nøytralt (&quot;Det gikk til venstre&quot;)</li><li><strong>Lær</strong> - Hent ut informasjon («Vinden er sterkere enn jeg trodde»)</li><li><strong>Tilbakestill</strong> - Gå fremover (3-pustetilbakestilling, øynene fremover)</li></ol><p><strong>Øvelse:</strong> &quot;Tenk på en nylig feil. Gå gjennom de tre trinnene.&quot;</p><hr><h4 id="del-6-integrering-og-avslutning-20-minutter" tabindex="-1">Del 6: Integrering og avslutning (20 minutter) <a class="header-anchor" href="#del-6-integrering-og-avslutning-20-minutter" aria-label="Permalink to &quot;Del 6: Integrering og avslutning (20 minutter)&quot;">​</a></h4><p><strong>Mål:</strong></p><ul><li>Konsolider læring</li><li>Lag handlingsplaner</li><li>Tilby ressurser</li></ul><p><strong>Refleksjonsspørsmål:</strong></p><ol><li>«Hvilken innsikt tar du med deg?»</li><li>&quot;Hva er én ting du skal prøve denne uken?&quot;</li><li>&quot;Hvilke spørsmål gjenstår?&quot;</li></ol><p><strong>Handlingsplanlegging (10 minutter)</strong></p><p>&quot;På utdelingsarket ditt, skriv:</p><ol><li>En teknikk du skal øve på denne uken</li><li>Når/hvor du skal øve på det</li><li>Hvordan du vil spore fremgangen din&quot;</li></ol><p><strong>Ressurser:</strong></p><ul><li>Del ut sammendragsark</li><li>Del nettsiden: carreau.app</li><li>Anbefalt startmodul: <a href="/no/utdanning/sonen/">Sonen</a></li></ul><p><strong>Sirkelen avsluttes:</strong> «Ett ord som beskriver hvordan du føler deg akkurat nå.»</p><p><strong>Sluttord:</strong> «Mental trening er en ferdighet som alle andre – det krever øvelse. Begynn i det små, vær tålmodig med deg selv, og legg merke til hva som forandrer seg. Takk for åpenheten din i dag.»</p><hr><h3 id="tips-for-tilretteleggeren" tabindex="-1">Tips for tilretteleggeren <a class="header-anchor" href="#tips-for-tilretteleggeren" aria-label="Permalink to &quot;Tips for tilretteleggeren&quot;">​</a></h3><h4 id="handtering-av-vanskelige-situasjoner" tabindex="-1">Håndtering av vanskelige situasjoner <a class="header-anchor" href="#handtering-av-vanskelige-situasjoner" aria-label="Permalink to &quot;Håndtering av vanskelige situasjoner&quot;">​</a></h4><p><strong>Hvis noen dominerer:</strong></p><ul><li>«Takk [navn]. La oss høre fra andre.»</li><li>Bruk strukturert turtaking</li></ul><p><strong>Hvis noen er motstandsdyktig:</strong></p><ul><li>Ikke krangle</li><li>«Det er et gyldig perspektiv. Hva synes andre?»</li><li>Samsvare seg med bekymringen deres</li></ul><p><strong>Hvis noen blir følelsesladet:</strong></p><ul><li>Normaliser det</li><li>«Dette berører noe ekte. Takk for at du deler.»</li><li>Ikke prøv å fikse</li></ul><p><strong>Hvis diskusjonen stopper opp:</strong></p><ul><li>Bruk spesifikke instruksjoner</li><li>Del ditt eget eksempel</li><li>Gå til en øvelse</li></ul><h4 id="energistyring" tabindex="-1">Energistyring <a class="header-anchor" href="#energistyring" aria-label="Permalink to &quot;Energistyring&quot;">​</a></h4><p><strong>Høy energi:</strong> Bruk trening og bevegelse <strong>Lav energi:</strong> Still provoserende spørsmål <strong>Spredt:</strong> Bring tilbake til strukturen <strong>Spenst:</strong> Bruk humor eller pause</p><h3 id="etter-økten" tabindex="-1">Etter økten <a class="header-anchor" href="#etter-økten" aria-label="Permalink to &quot;Etter økten&quot;">​</a></h3><p><strong>Oppfølging:</strong></p><ul><li>Send sammendrags-e-post innen 24 timer</li><li>Inkluder lenker til ressurser</li><li>Tilby å svare på spørsmål</li><li>Planlegg valgfri oppfølgingstime</li></ul><p><strong>Selvrefleksjon:</strong></p><ul><li>Hva fungerte bra?</li><li>Hva ville du endret?</li><li>Hva overrasket deg?</li><li>Hva lærte du?</li></ul><hr><h2 id="materialer" tabindex="-1">Materialer <a class="header-anchor" href="#materialer" aria-label="Permalink to &quot;Materialer&quot;">​</a></h2><ul><li><a href="/no/mental-reise/materialer#deltakerguide">Deltakerguide</a></li><li><a href="/no/mental-reise/materialer#slides-for-veileder">Slides for veileder</a></li><li><a href="/no/mental-reise/materialer#sammendragsark">Sammendragsark</a></li><li><a href="/no/mental-reise/materialer#øvingsark">Øvelsesark</a></li></ul><hr><div class="tip custom-block"><p class="custom-block-title">Klar til å tilrettelegge?</p><ol><li>Les denne veiledningen grundig</li><li>Last ned materialer</li><li>Øv på øvelsene selv</li><li>Planlegg økten din</li><li>Stol på prosessen</li></ol></div>',140))])}]]);export{u as __pageData,g as default};
